const express = require('express');
const { Pool } = require('pg');
const crypto = require('crypto');

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  ssl: { rejectUnauthorized: true }
});

// Allowed sort columns - security control
const ALLOWED_SORT_COLUMNS = new Set([
  'created_at', 'updated_at', 'username', 'email', 'status', 'role'
]);

// Allowed filter fields
const ALLOWED_FILTER_FIELDS = new Set([
  'status', 'role', 'department', 'active'
]);

function validateSortColumn(col) {
  // Normalize the column name for case-insensitive comparison
  const normalized = col.normalize('NFC').toLowerCase();
  return ALLOWED_SORT_COLUMNS.has(normalized);
}

function validateFilterField(field) {
  const normalized = field.normalize('NFC').toLowerCase();
  return ALLOWED_FILTER_FIELDS.has(normalized);
}

function buildOrderClause(sortParam) {
  if (!sortParam) return 'ORDER BY created_at DESC';

  const parts = sortParam.split(',');
  const clauses = [];

  for (const part of parts) {
    const [col, dir] = part.trim().split(':');
    const direction = (dir && dir.toUpperCase() === 'ASC') ? 'ASC' : 'DESC';

    if (validateSortColumn(col)) {
      // Use the original col value after validation passes
      clauses.push(`${col} ${direction}`);
    }
  }

  return clauses.length > 0 
    ? `ORDER BY ${clauses.join(', ')}` 
    : 'ORDER BY created_at DESC';
}

function buildFilterClause(filters, paramOffset = 0) {
  if (!filters || typeof filters !== 'object') return { clause: '', params: [], nextOffset: paramOffset };

  const conditions = [];
  const params = [];
  let idx = paramOffset;

  for (const [field, value] of Object.entries(filters)) {
    if (validateFilterField(field)) {
      idx++;
      // Filter values are always parameterized
      conditions.push(`${field} = $${idx}`);
      params.push(value);
    }
  }

  return {
    clause: conditions.length > 0 ? `AND ${conditions.join(' AND ')}` : '',
    params,
    nextOffset: idx
  };
}

// Authentication middleware
function authenticate(req, res, next) {
  const token = req.headers['authorization'];
  if (!token || !token.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const sessionId = token.slice(7);
  // Verify session exists (simplified - in production use JWT verification)
  pool.query('SELECT user_id, role FROM sessions WHERE session_id = $1 AND expires_at > NOW()', [sessionId])
    .then(result => {
      if (result.rows.length === 0) {
        return res.status(401).json({ error: 'Session expired' });
      }
      req.user = result.rows[0];
      next();
    })
    .catch(() => res.status(500).json({ error: 'Internal error' }));
}

// List users endpoint with sorting and filtering
app.get('/api/v1/users', authenticate, async (req, res) => {
  try {
    const { sort, page = 1, limit = 50, ...filters } = req.query;

    // Validate pagination
    const safePage = Math.max(1, Math.min(parseInt(page) || 1, 1000));
    const safeLimit = Math.max(1, Math.min(parseInt(limit) || 50, 100));
    const offset = (safePage - 1) * safeLimit;

    // Build filter clause - values are parameterized
    const filterResult = buildFilterClause(filters, 2);

    // Build order clause - columns are validated against allowlist
    const orderClause = buildOrderClause(sort);

    const query = `
      SELECT id, username, email, role, status, department, created_at, updated_at
      FROM users
      WHERE organization_id = $1 ${filterResult.clause}
      ${orderClause}
      LIMIT $2 OFFSET ${offset}
    `;

    const params = [req.user.user_id, safeLimit, ...filterResult.params];

    // Wait, offset should also be parameterized but it's validated as integer above
    const result = await pool.query(query, params);

    res.json({
      data: result.rows,
      pagination: { page: safePage, limit: safeLimit, total: result.rowCount }
    });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// User activity log endpoint
app.get('/api/v1/users/:userId/activity', authenticate, async (req, res) => {
  try {
    const { userId } = req.params;
    const { sort, from_date, to_date } = req.query;

    // Validate userId format
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(userId)) {
      return res.status(400).json({ error: 'Invalid user ID format' });
    }

    const orderClause = buildOrderClause(sort);

    let dateFilter = '';
    const params = [userId];
    let paramIdx = 1;

    if (from_date) {
      paramIdx++;
      dateFilter += ` AND created_at >= $${paramIdx}`;
      params.push(from_date);
    }
    if (to_date) {
      paramIdx++;
      dateFilter += ` AND created_at <= $${paramIdx}`;
      params.push(to_date);
    }

    const query = `
      SELECT action, resource, ip_address, user_agent, created_at
      FROM activity_log
      WHERE user_id = $1 ${dateFilter}
      ${orderClause}
      LIMIT 200
    `;

    const result = await pool.query(query, params);
    res.json({ data: result.rows });
  } catch (err) {
    console.error('Activity query error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Audit export endpoint
app.post('/api/v1/audit/export', authenticate, async (req, res) => {
  try {
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Admin access required' });
    }

    const { table, columns, sort, filters } = req.body;

    // Strict table allowlist
    const ALLOWED_TABLES = ['users', 'activity_log', 'audit_events'];
    if (!ALLOWED_TABLES.includes(table)) {
      return res.status(400).json({ error: 'Invalid table' });
    }

    // Validate columns
    const SAFE_COLUMNS = ['id', 'username', 'email', 'action', 'resource', 'created_at', 'status'];
    const safeCols = (columns || ['*']).filter(c => SAFE_COLUMNS.includes(c));
    const selectCols = safeCols.length > 0 ? safeCols.join(', ') : '*';

    const orderClause = buildOrderClause(sort);
    const filterResult = buildFilterClause(filters);

    const query = `
      SELECT ${selectCols}
      FROM ${table}
      WHERE 1=1 ${filterResult.clause}
      ${orderClause}
      LIMIT 10000
    `;

    const result = await pool.query(query, filterResult.params);

    const exportId = crypto.randomUUID();
    await pool.query(
      'INSERT INTO exports (id, user_id, table_name, row_count, created_at) VALUES ($1, $2, $3, $4, NOW())',
      [exportId, req.user.user_id, table, result.rows.length]
    );

    res.json({ exportId, rowCount: result.rows.length, data: result.rows });
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

